mapper.select:
SELECT id, user_id, expires_at, revoked_at
FROM refresh_tokens
WHERE token_hash = #{tokenHash}

mapper.update:
UPDATE refresh_tokens
SET revoked_at = #{now}
WHERE id = #{id}
  AND revoked_at IS NULL

UPDATE refresh_tokens
SET revoked_at = #{now}
WHERE user_id = #{userId}
  AND revoked_at IS NULL
